[package]
name = "ascent-review"
version = "0.1.0"
edition.workspace = true
rust-version.workspace = true

[dependencies]
ascent-domain = { path = "../ascent-domain" }
ascent-sim = { path = "../ascent-sim" }
ascent-aero = { path = "../ascent-aero" }
serde = { workspace = true }
serde_json = { workspace = true }

[dev-dependencies]
approx = { workspace = true }
# ascent-mcp: MCP stdio adapter over the copilot seam (v0.4, Pillar 3).
#
# Dependency justification: zero new external deps. The MCP 2026-07-28
# protocol subset a stdio tool server needs (JSON-RPC 2.0, newline-delimited,
# initialize/tools/tasks) is small enough to hand-roll on serde_json — the
# official rmcp SDK was evaluated and rejected for V1 because it drags in a
# tokio async-network runtime, which fights the no-runtime-network invariant
# and the zero-unjustified-deps rule for what is a synchronous local pipe.
[package]
name = "ascent-mcp"
version = "0.0.0"
edition.workspace = true
rust-version.workspace = true
license.workspace = true

[dependencies]
ascent-app = { path = "../ascent-app" }
serde = { workspace = true }
serde_json = { workspace = true }

[[bin]]
name = "ascent-mcp"
path = "src/main.rs"
[workspace]
resolver = "2"
members = [
    "crates/ascent-domain",
    "crates/ascent-sim",
    "crates/ascent-aero",
    "crates/ascent-app",
    "crates/ascent-review",
    "crates/ascent-mcp",
    "xtask",
]

[workspace.package]
version = "0.1.0"
edition = "2021"
license = "MIT"
# MSRV: the toolchain CI builds and tests with. Raising it is a
# deliberate, changelogged decision, not a side effect.
rust-version = "1.97"

[workspace.dependencies]
serde = { version = "1", features = ["derive"] }
serde_json = { version = "1", features = ["float_roundtrip"] }
sha2 = "0.10"
thiserror = "2"
approx = "0.5"
