        assert!(Vehicle::from_tree(&no_fins).unwrap_err().contains("fin set"));
        let mut no_nose = reference_vehicle();
        no_nose.parts.remove(0);
        assert!(Vehicle::from_tree(&no_nose).unwrap_err().contains("nose"));
