    repair_for(&ascent_domain::vehicle::reference_vehicle(), &crate::design::Design::reference(), target_apogee_m)
}

pub fn repair_for(tree: &TreeVehicle, flat_design: &crate::design::Design, target_apogee_m: f64) -> Result<Repair, String> {
    let design = review_from_tree(tree, flat_design)?;
