import type { Design } from "../core/types";

interface Props {
  design: Design;
  onChange: (next: Design) => void;
}

function Num({
  label,
  value,
  step,
  onChange,
}: {
  label: string;
  value: number;
  step?: number;
  onChange: (v: number) => void;
}) {
  return (
    <label style={{ display: "block", margin: "6px 0" }}>
      <span style={{ display: "inline-block", width: 150 }}>{label}</span>
      <input
        type="number"
        value={value}
        step={step ?? 1}
        style={{ width: 90 }}
        onChange={(e) => {
          const v = Number(e.target.value);
          if (Number.isFinite(v)) onChange(v);
        }}
      />
    </label>
  );
}

export default function Inspector({ design, onChange }: Props) {
  return (
    <div>
      <h3>Rocket</h3>
      <label style={{ display: "block", margin: "6px 0" }}>
        <span style={{ display: "inline-block", width: 150 }}>Name</span>
        <input
          value={design.name}
          onChange={(e) => onChange({ ...design, name: e.target.value })}
        />
      </label>
      <Num
        label="Dry mass (g)"
        value={design.dry_mass_g}
        onChange={(v) => onChange({ ...design, dry_mass_g: v })}
      />
      <Num
        label="Diameter (mm)"
        value={design.diameter_mm}
        onChange={(v) => onChange({ ...design, diameter_mm: v })}
      />
      <Num
        label="Drag Cd"
        value={design.cd}
        step={0.01}
        onChange={(v) => onChange({ ...design, cd: v })}
      />
      <Num
        label="Rail length (m)"
        value={design.rail_length_m}
        step={0.1}
        onChange={(v) => onChange({ ...design, rail_length_m: v })}
      />
      <h3>Recovery</h3>
      <label style={{ display: "block", margin: "6px 0" }}>
        <span style={{ display: "inline-block", width: 150 }}>Parachute</span>
        <input
          type="checkbox"
          checked={design.chute.enabled}
          onChange={(e) =>
            onChange({ ...design, chute: { ...design.chute, enabled: e.target.checked } })
          }
        />
      </label>
      {design.chute.enabled && (
        <>
          <Num
            label="Chute diameter (cm)"
            value={design.chute.diameter_cm}
            onChange={(v) =>
              onChange({ ...design, chute: { ...design.chute, diameter_cm: v } })
            }
          />
          <Num
            label="Chute Cd"
            value={design.chute.cd}
            step={0.05}
            onChange={(v) => onChange({ ...design, chute: { ...design.chute, cd: v } })}
          />
        </>
      )}
    </div>
  );
}

import type { Command, Design } from "./types";

const SCALAR_FIELDS = ["name", "dry_mass_g", "diameter_mm", "cd", "rail_length_m"] as const;
const CHUTE_FIELDS = ["enabled", "diameter_cm", "cd"] as const;

export function diffDesign(prev: Design, next: Design): Command[] {
  const cmds: Command[] = [];
  for (const field of SCALAR_FIELDS) {
    if (prev[field] !== next[field]) {
      cmds.push({ cmd: "set_sim_param", param: field, value: next[field] });
    }
  }
  for (const field of CHUTE_FIELDS) {
    if (prev.chute[field] !== next.chute[field]) {
      cmds.push({ cmd: "set_sim_param", param: `chute.${field}`, value: next.chute[field] });
    }
  }
  if (prev.motor_designation !== next.motor_designation) {
    cmds.push({ cmd: "select_motor", designation: next.motor_designation });
  }
  return cmds;
}

import { describe, expect, it } from "vitest";
import { diffDesign } from "./commandDiff";
import type { Design } from "./types";

const base: Design = {
  name: "Estes Alpha III",
  dry_mass_g: 34,
  diameter_mm: 25,
  cd: 0.6,
  chute: { enabled: true, diameter_cm: 30, cd: 0.75 },
  motor_designation: "C6",
  rail_length_m: 0.9,
};

describe("diffDesign", () => {
  it("returns nothing for an identical design", () => {
    expect(diffDesign(base, { ...base, chute: { ...base.chute } })).toEqual([]);
  });

  it("names a single scalar change", () => {
    expect(diffDesign(base, { ...base, cd: 0.7 })).toEqual([
      { cmd: "set_sim_param", param: "cd", value: 0.7 },
    ]);
  });

  it("uses dotted paths for chute fields", () => {
    expect(diffDesign(base, { ...base, chute: { ...base.chute, diameter_cm: 45 } })).toEqual([
      { cmd: "set_sim_param", param: "chute.diameter_cm", value: 45 },
    ]);
  });

  it("routes motor changes through select_motor", () => {
    expect(diffDesign(base, { ...base, motor_designation: "B6" })).toEqual([
      { cmd: "select_motor", designation: "B6" },
    ]);
  });

  it("emits one command per changed field", () => {
    const next: Design = {
      ...base,
      dry_mass_g: 40,
      chute: { ...base.chute, enabled: false },
      motor_designation: "B6",
    };
    expect(diffDesign(base, next)).toEqual([
      { cmd: "set_sim_param", param: "dry_mass_g", value: 40 },
      { cmd: "set_sim_param", param: "chute.enabled", value: false },
      { cmd: "select_motor", designation: "B6" },
    ]);
  });
});

