export interface StudyResults {
  input_hash: string;
  data: Record<string, unknown>;
}

export interface Study {
  id: number;
  name: string;
  kind: StudyKind;
  engine: string;
  seed: number;
  results?: StudyResults;
}

export interface DocumentState {
  vehicle: Vehicle;
  design: Design;
  studies: Study[];
  atmosphere?: AtmosphereProfile;
