/** Assign only optional visualization modules. Shared startup dependencies
 * such as React deliberately return undefined and remain in the entry graph. */
export const VISUALIZATION_CHUNKS = Object.assign(
  (id: string): string | undefined => {
    const path = id.replaceAll("\\", "/");
    if (path.includes("/node_modules/three/")) return "vendor-three";
    if (path.includes("/node_modules/@react-three/fiber/")) return "vendor-r3f";
    if (
      path.includes("/node_modules/@react-three/drei/") ||
      path.includes("/node_modules/camera-controls/")
    ) {
      return "vendor-drei";
    }
    return undefined;
  },
  { onlyExplicit: true as const },
);

