  // Ignored if `include_body=True`. Default 0.
  depth?: number;
  // (optional) list of LSP symbol kinds (integers) to exclude.
  exclude_kinds?: Array<number>;
  // Whether to include the symbol's source code. Use judiciously.
  include_body?: boolean;
  // Whether to include additional info (hover-like, typically including docstring and signature),
  // about the symbol (ignored if include_body is True). Info is never included for child symbols.
  // Note: Depending on the language, this can be slow (e.g., C/C++).
  include_info?: boolean;
  // (optional) limits results to the given LSP symbol kinds (integers).
  include_kinds?: Array<number>;
  // Max result length; -1 for default.
  max_answer_chars?: number;
  // Maximum number of permitted matches. If exceeded, a shortened result is returned
  // which allows refining the search. -1 (default) means no limit. Set to 1 if you search for a single symbol.
  max_matches?: number;
  // The name path matching pattern (see above).
  name_path_pattern: string;
  // (optional) restrict search to this file or directory. If None, searches entire codebase.
  // If a directory is passed, the search will be restricted to the files in that directory.
  // If a file is passed, the search will be restricted to that file.
  relative_path?: string;
  // If True, use substring matching for the last element of the pattern, such that
  // "Foo/get" would match "Foo/getValue" and "Foo/getData".
  substring_matching?: boolean;
}): Promise<CallToolResult<{ result: string; }>>; };
